-- The gate, enforced in both places that could open it
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION roll_gu_drop(p_player_id BIGINT, p_region TEXT, p_rank SMALLINT DEFAULT 1)
RETURNS BIGINT
LANGUAGE plpgsql
AS $$
DECLARE
    picked BIGINT;
BEGIN
    IF random() >= game_config_value('gu_drop_chance') THEN
        RETURN NULL;
    END IF;

    -- Nothing hands out a Gu of a higher rank than the thing guarding it, and
    -- nothing hands out an Immortal Gu at all yet.
    SELECT d.gu_type_id INTO picked
    FROM gu_region_drops d
    JOIN gu_types t ON t.gu_type_id = d.gu_type_id
    WHERE d.region_code = p_region
      AND t.rank <= LEAST(GREATEST(p_rank, 1),
                          game_config_value('gu_max_droppable_rank'))
    ORDER BY -ln(random()) / d.weight
    LIMIT 1;

    IF picked IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN grant_gu(p_player_id, picked, p_region);
END;
$$;

COMMENT ON FUNCTION roll_gu_drop(BIGINT, TEXT, SMALLINT) IS
    'A whole Gu off a corpse: rare, regional, never above the rank of what dropped it, and never above the rank the world has opened.';

-- A drop row above the gate would be a Gu the function refuses and the region
-- index advertises. The table refuses it instead.
CREATE FUNCTION gu_region_drop_respects_the_gate()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    r SMALLINT;
BEGIN
    SELECT rank INTO r FROM gu_types WHERE gu_type_id = NEW.gu_type_id;

    IF r > game_config_value('gu_max_droppable_rank') THEN
        RAISE EXCEPTION
            'rank % is above the rank the world hands out (%); raise gu_max_droppable_rank first',
            r, game_config_value('gu_max_droppable_rank')
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER gu_region_drops_respect_the_gate
    BEFORE INSERT OR UPDATE ON gu_region_drops
    FOR EACH ROW EXECUTE FUNCTION gu_region_drop_respects_the_gate();


-- ---------------------------------------------------------------------------
-- Asking the data whether any of that is true
-- ---------------------------------------------------------------------------

DO $$
DECLARE
    n       BIGINT;
    worst   NUMERIC;
    highest SMALLINT;
    who     BIGINT;
    mark    BIGINT;
BEGIN
    SELECT count(*) INTO n FROM gu_types;
    IF n < 2800 THEN
        RAISE EXCEPTION 'only % Gu in the catalogue', n;
    END IF;

    SELECT count(*) INTO n FROM gu_types t
    WHERE NOT EXISTS (SELECT 1 FROM gu_type_effects e
                      WHERE e.gu_type_id = t.gu_type_id);
    IF n > 0 THEN
        RAISE EXCEPTION '% Gu lend nothing', n;
    END IF;

    SELECT count(*) INTO n FROM gu_types t
    WHERE NOT EXISTS (SELECT 1 FROM gu_recipes r
                      WHERE r.gu_type_id = t.gu_type_id);
    IF n > 0 THEN
        RAISE EXCEPTION '% Gu cannot be made', n;
    END IF;

    -- No recipe may floor below the failure threshold with room to spare, or
    -- an empty bench destroys the materials every time.
    SELECT min(50 + material_affinity(c.base_material, c.path_code)
                  + material_affinity(c.secondary_material, c.path_code))
    INTO worst FROM gu_recipe_costs c;
    IF worst < game_config_value('gu_refine_failure_threshold') + 15 THEN
        RAISE EXCEPTION 'a recipe floors at %, and an empty bench would destroy it', worst;
    END IF;

    -- Every rarity still has a price, or its Gu fall out of /refine silently.
    SELECT count(*) INTO n FROM gu_types t
    WHERE NOT EXISTS (SELECT 1 FROM gu_refine_rarity_costs m WHERE m.rarity = t.rarity);
    IF n > 0 THEN
        RAISE EXCEPTION '% Gu have a rarity nothing prices', n;
    END IF;

    -- The gate, from the table's side.
    SELECT max(t.rank) INTO highest
    FROM gu_region_drops d JOIN gu_types t ON t.gu_type_id = d.gu_type_id;
    IF highest > game_config_value('gu_max_droppable_rank') THEN
        RAISE EXCEPTION 'rank % is still placed in a region', highest;
    END IF;

    -- And from the function's side, by moving the gate rather than by trusting
    -- it. Inside a subtransaction that is thrown away: drop the ceiling to 1,
    -- roll a rank 9 kill three thousand times, and every Gu handed over in
    -- that window must be rank 1. A function that ignored the config would
    -- hand out rank 5s and fail here.
    SELECT p.player_id INTO who FROM players p
    WHERE p.deleted_at IS NULL AND p.discord_id <> 0 LIMIT 1;

    IF who IS NULL THEN
        RAISE NOTICE 'nobody to roll for; the tests carry the gate';
    ELSE
        BEGIN
            SELECT COALESCE(max(gu_id), 0) INTO mark FROM player_gu;
            UPDATE game_config SET value = 1 WHERE key = 'gu_max_droppable_rank';

            PERFORM roll_gu_drop(who, 'northern', 9::smallint)
            FROM generate_series(1, 3000);

            SELECT count(*) INTO n FROM player_gu WHERE gu_id > mark;
            IF n = 0 THEN
                RAISE EXCEPTION 'three thousand rolls yielded nothing to check';
            END IF;

            SELECT max(t.rank) INTO highest
            FROM player_gu g JOIN gu_types t ON t.gu_type_id = g.gu_type_id
            WHERE g.gu_id > mark;

            IF highest > 1 THEN
                RAISE EXCEPTION
                    'the ceiling was 1 and a rank % Gu came out anyway', highest;
            END IF;

            RAISE EXCEPTION 'probe-ok';
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLERRM <> 'probe-ok' THEN
                    RAISE;
                END IF;
        END;
    END IF;

    -- Every Path leads somewhere findable, or a focus is a dead end.
    SELECT count(*) INTO n FROM paths p
    WHERE NOT EXISTS (
        SELECT 1 FROM gu_region_drops d
        JOIN gu_types t ON t.gu_type_id = d.gu_type_id
        WHERE t.path_code = p.code);
    IF n > 0 THEN
        RAISE EXCEPTION '% Paths have no Gu anybody can find', n;
    END IF;
END;
$$;
